import os
import torch


class Config:
    # ==========================================
    # Directories & Paths
    # ==========================================
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"

    # Metadata Paths (Generated by previous steps)
    TRAIN_METADATA_PATH = os.path.join(METADATA_DIR, "train_metadata.csv")
    VAL_METADATA_PATH = os.path.join(METADATA_DIR, "val_metadata.csv")
    TEST_METADATA_PATH = os.path.join(METADATA_DIR, "test_metadata.csv")

    # Working Directory for Caching and Models
    # Stores processed tensors, cached file lists, and model checkpoints
    WORKING_DIR = "./working/idea_8"
    os.makedirs(WORKING_DIR, exist_ok=True)

    # Submission Path
    SUBMISSION_PATH = "./submission/submission.csv"
    os.makedirs(os.path.dirname(SUBMISSION_PATH), exist_ok=True)

    # ==========================================
    # Data Processing Configuration
    # ==========================================
    IMG_SIZE = 224

    # Modalities to use (FLAIR, T1wCE, T2w)
    # These match the column names in the metadata CSVs
    MODALITY_COLS = ["flair_path", "t1wce_path", "t2w_path"]

    # Slice Selection Strategy
    # We select 1 middle slice per modality to avoid noise from adjacent slices
    # Cite solution_lesson_node_00025
    SLICE_DEPTH = 1

    # Total Input Channels = Number of Modalities * Slices per Modality
    # 3 modalities * 1 slice = 3 channels (RGB-like)
    IN_CHANNELS = len(MODALITY_COLS) * SLICE_DEPTH

    # ==========================================
    # Model Configuration
    # ==========================================
    BACKBONE = "efficientnet_b0"
    PRETRAINED = True
    NUM_CLASSES = 1

    # ==========================================
    # Training Hyperparameters
    # ==========================================
    SEED = 42
    N_FOLDS = 5
    EPOCHS = 15
    BATCH_SIZE = 32

    # Optimization
    LEARNING_RATE = 1e-4
    WEIGHT_DECAY = 1e-2  # Aggressive regularization for small dataset
    DROPOUT_RATE = 0.2

    # Early Stopping
    EARLY_STOPPING_PATIENCE = 5

    # ==========================================
    # Compute & Runtime
    # ==========================================
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"
    NUM_WORKERS = 4

    # ==========================================
    # Debugging / Development
    # ==========================================
    # Set DEBUG to True to run on a small subset of data for testing
    DEBUG = False
    DEBUG_SAMPLES = 32
